package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.regex.Pattern;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;

/** Body of a claim add or edit, as typed: the amount, the date (blank for the sheet's today),
 *  the note, the number of the claim it corrects (blank for none), who makes the change and the
 *  external reference (blank for none). */
public record ClaimRequest(String amount, String date, String note, String corrects, String user, String ref) {
    /** Up to two decimals; negative only for a correction. */
    private static final Pattern AMOUNT = Pattern.compile("-?\\d+(\\.\\d{1,2})?");
    private static final Pattern NUMBER = Pattern.compile("\\d+|.+-\\d+");

    /** The request's values as the claim rules accept them, or refused. A negative amount is a
     *  correction and must name the number of the claim it corrects; any other claim corrects none. */
    public static ClaimValues checked(ClaimRequest request) throws InvalidSheetRequestException {
        String amount = request == null || request.amount() == null ? "" : request.amount().trim();
        if (!AMOUNT.matcher(amount).matches()) {
            throw new InvalidSheetRequestException("The amount must be a number with up to two decimals");
        }
        BigDecimal value = new BigDecimal(amount).setScale(2);
        String rawCorrects = request.corrects() == null ? "" : request.corrects().trim();
        String corrects = null;
        if (value.signum() < 0) {
            if (!NUMBER.matcher(rawCorrects).matches()) {
                throw new InvalidSheetRequestException("A negative amount must name the number of the settled claim it corrects");
            }
            corrects = rawCorrects;
        }
        String rawDate = request.date() == null ? "" : request.date().trim();
        LocalDate date = null;
        if (!rawDate.isEmpty()) {
            try {
                date = LocalDate.parse(rawDate);
            } catch (DateTimeParseException e) {
                throw new InvalidSheetRequestException("Not a date (yyyy-mm-dd): " + rawDate);
            }
        }
        String note = request.note() == null ? "" : request.note();
        String ref = request.ref() == null || request.ref().isBlank() ? null : request.ref().trim();
        return new ClaimValues(value, date, note, corrects, request.user(), ref);
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.holiday.Holidays;
import net.officefloor.hq.app.period.ClosedPeriods;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRetiredException;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Builds the new claim, its due-by fixed from its person's own terms, else those of their grade in force on its date, a late entry when a soft-closed period contains its due-by, refusing one due by in a closed period or after its person's retirement date,
 *  and a correction that does not name a SETTLED claim of the same person. */
public class BuildClaim {
    public void build(@Val ClaimValues values, @Val Person person, Sheets sheets, ClosedPeriods closedPeriods,
            Claims claims, Settings settings, Holidays holidays, Out<Claim> claim) throws PeriodClosedException, PersonRetiredException, InvalidSheetRequestException {
        claim.set(built(values, person, sheets, closedPeriods, claims, settings, holidays));
    }

    /** The new DRAFT claim for these values and person, or refused by the claim form's rules. */
    static Claim built(ClaimValues values, Person person, Sheets sheets, ClosedPeriods closedPeriods,
            Claims claims, Settings settings, Holidays holidays) throws PeriodClosedException, PersonRetiredException, InvalidSheetRequestException {
        LocalDate date = values.date() != null ? values.date() : settings.claimDate(person.getSheetId());
        LocalDate dueBy = DueBy.of(person, date, settings, holidays);
        closedPeriods.refuse(person.getSheetId(), dueBy);
        person.refuseRetired(date);
        refuseUncorrected(values, person.getSheetId(), person.getId(), claims);
        refuseUsedRef(values.ref(), person.getSheetId(), null, claims);
        Claim built = new Claim(null, person.getSheetId(), person.getId(), values.amount(), date, values.note(),
                ClaimStatus.DRAFT, null, null, null);
        built.setCorrects(values.corrects());
        built.setRef(values.ref());
        built.setDueBy(dueBy);
        built.setLateEntry(closedPeriods.late(person.getSheetId(), dueBy));
        return built;
    }

    /** Refuses a reference another claim on the sheet (not `ownId`) already has, without regard to case. */
    static void refuseUsedRef(String ref, String sheetId, Long ownId, Claims claims) throws InvalidSheetRequestException {
        if (ref != null && claims.refUsed(sheetId, ref, ownId)) {
            throw new InvalidSheetRequestException("The reference is already used on the sheet: " + ref);
        }
    }

    /** Refuses a correction whose number is not a SETTLED claim of the same person. */
    static void refuseUncorrected(ClaimValues values, String sheetId, long personId, Claims claims)
            throws InvalidSheetRequestException {
        if (values.corrects() != null && !claims.settled(sheetId, personId, values.corrects())) {
            throw new InvalidSheetRequestException("A correction must name a settled claim of the same person: " + values.corrects());
        }
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.period.ClosedPeriods;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRetiredException;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;

/** Edits the claim and releases its editor's lock, refusing when another user's editor locks it, or it is no longer a DRAFT, or is due by in a closed period (its due-by, fixed when it was added, stays as it is),
 *  or would be dated after its person's retirement date, or would be a correction of no SETTLED claim of its person. */
public class ApplyClaim {
    public void apply(@Val ClaimValues values, @Val Claim claim, Sheets sheets, ClosedPeriods closedPeriods,
            People people, Claims claims)
            throws ClaimEditRefusedException, ClaimLockedException, PeriodClosedException, PersonRetiredException, InvalidSheetRequestException {
        ApplyClaimLock.refuseLocked(claim, values.user());
        if (claim.getStatus() != ClaimStatus.DRAFT) {
            throw new ClaimEditRefusedException(claim.getStatus());
        }
        LocalDate date = values.date() != null ? values.date() : sheets.today(claim.getSheetId());
        closedPeriods.refuse(claim.getSheetId(), claim.getDueBy());
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        if (person != null) person.refuseRetired(date);
        BuildClaim.refuseUncorrected(values, claim.getSheetId(), claim.getPersonId(), claims);
        BuildClaim.refuseUsedRef(values.ref(), claim.getSheetId(), claim.getId(), claims);
        claim.setAmount(values.amount());
        claim.setDate(date);
        claim.setNote(values.note());
        claim.setCorrects(values.corrects());
        claim.setRef(values.ref());
        claim.setLockedBy(null);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A claim a person on a sheet has made, DRAFT (and unnumbered) until it is opened. `id` is null until the claim is first saved. */
public class Claim {
    private Long id;
    private final String sheetId;
    private long personId;
    private BigDecimal amount;
    private LocalDate date;
    private String note;
    private ClaimStatus status;
    private String number;
    private BigDecimal due;
    private String openedBy;
    private boolean stated;
    private BigDecimal statedDue;
    private String corrects;
    private LocalDate dueBy;
    private LocalDate deferredUntil;
    private boolean deferred;
    private int proofs;
    private String splitFrom;
    private String lockedBy;
    private boolean lateEntry;
    private LocalDate remindedOn;
    private String ref;

    public Claim(Long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
            ClaimStatus status, String number, BigDecimal due, String openedBy) {
        this.id = id;
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.note = note;
        this.status = status;
        this.number = number;
        this.due = due;
        this.openedBy = openedBy;
    }

    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }
    public String getSheetId() { return sheetId; }
    public long getPersonId() { return personId; }
    public void setPersonId(long personId) { this.personId = personId; }
    public BigDecimal getAmount() { return amount; }
    public void setAmount(BigDecimal amount) { this.amount = amount; }
    public LocalDate getDate() { return date; }
    public void setDate(LocalDate date) { this.date = date; }
    public String getNote() { return note; }
    public void setNote(String note) { this.note = note; }
    public ClaimStatus getStatus() { return status; }
    public void setStatus(ClaimStatus status) { this.status = status; }
    /** The claim's number on its sheet, given when it is opened (sheet-wide "7", or within its period "P1-2" / "X-1"); null for a DRAFT, or a claim voided while a DRAFT. A voided claim keeps its number. */
    public String getNumber() { return number; }
    public void setNumber(String number) { this.number = number; }
    /** The due fixed when the claim was settled; null when it has none (not settled, or settled with no rate). */
    public BigDecimal getDue() { return due; }
    public void setDue(BigDecimal due) { this.due = due; }
    /** The user who opened the claim; null while it has not been opened. */
    public String getOpenedBy() { return openedBy; }
    public void setOpenedBy(String openedBy) { this.openedBy = openedBy; }
    /** Whether the claim is bound by its person's last statement to the figure it had then. */
    public boolean isStated() { return stated; }
    public void setStated(boolean stated) { this.stated = stated; }
    /** The figure the last statement bound the claim to; null when unbound, or bound to n/a. */
    public BigDecimal getStatedDue() { return statedDue; }
    public void setStatedDue(BigDecimal statedDue) { this.statedDue = statedDue; }
    /** The number of the SETTLED claim of the same person this correction corrects; null when it is not a correction. */
    public String getCorrects() { return corrects; }
    public void setCorrects(String corrects) { this.corrects = corrects; }
    /** The date the claim is due by, fixed when it was added: its date then plus the terms of its
     *  person's grade in force on that date. Later changes to the terms or the claim's date leave it. */
    public LocalDate getDueBy() { return dueBy; }
    public void setDueBy(LocalDate dueBy) { this.dueBy = dueBy; }
    /** The date the claim was last deferred until; null when it never was. */
    public LocalDate getDeferredUntil() { return deferredUntil; }
    public void setDeferredUntil(LocalDate deferredUntil) { this.deferredUntil = deferredUntil; }
    /** Whether the claim is deferred now: OPEN, and the sheet's today (as it was when the claim was
     *  read) is before its deferred-until date. A deferred claim counts in no total, is not overdue,
     *  cannot be settled and is left unbound by a statement. */
    public boolean isDeferred() { return deferred && status == ClaimStatus.OPEN; }
    public void setDeferred(boolean deferred) { this.deferred = deferred; }
    /** How many proofs the claim has: a claim whose due is above the sheet's proof threshold on its
     *  date cannot be settled or approved while it has none. */
    public int getProofs() { return proofs; }
    public void setProofs(int proofs) { this.proofs = proofs; }
    /** The number of the claim this one was split off; null when it was not split off one. */
    public String getSplitFrom() { return splitFrom; }
    public void setSplitFrom(String splitFrom) { this.splitFrom = splitFrom; }
    /** The user whose open editor locks the claim for everyone else; null when no editor holds it. */
    public String getLockedBy() { return lockedBy; }
    public void setLockedBy(String lockedBy) { this.lockedBy = lockedBy; }
    /** Whether the claim was added while its period was soft-closed. */
    public boolean isLateEntry() { return lateEntry; }
    public void setLateEntry(boolean lateEntry) { this.lateEntry = lateEntry; }
    /** The last day (sheet-today) a reminder was written for the claim; null when it never was. */
    public LocalDate getRemindedOn() { return remindedOn; }
    public void setRemindedOn(LocalDate remindedOn) { this.remindedOn = remindedOn; }
    /** The claim's external reference, unique on its sheet without regard to case; null when it has none. */
    public String getRef() { return ref; }
    public void setRef(String ref) { this.ref = ref; }
    /** Whether the claim is a correction: its amount is negative. Its due has no floor and no late charge. */
    public boolean isCorrection() { return amount.signum() < 0; }
}
